/**
 * @defgroup ikun_image Image2Lcd Exported Image Data
 * @brief Color image data exported by Image2Lcd v2.9
 *
 * Export settings (from Image2Lcd v2.9 interface):
 *   - Output data type:     C array (*.c)
 *   - Scan mode:            Vertical scan (column-by-column, top-to-bottom)
 *   - Output gray:          16-bit true color (RGB565)
 *   - Include image header: Enabled (8-byte header)
 *   - MSB first:            Enabled (high byte of each pixel stored first)
 *
 * The array begins with an 8-byte Image2Lcd header:
 *   [0]=scan mode, [1]=0x10 (16-bit), [2..3]=width (LE),
 *   [4..5]=height (LE), [6..7]=reserved
 * followed by RGB565 pixel data in MSB-first vertical-scan order.
 *
 * Use in your application:
 *   lcd_draw_image2lcd(100, 60, gImage_ikun_image, 120, 120);
 */

